                q=(y+dy,x+dx)
                if 0<=q[0]<h and 0<=q[1]<w and grid[q[0]][q[1]] and q not in seen:
                  seen.add(q); todo.append(q)
          comps.append(cells)
    # Locate target by repeatedly overlaying component shapes at candidate offsets;
