def transform(grid):
    # Select the lowest isolated foreground figure; return its tight bounding box.
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] and (r, c) not in seen:
                todo = [(r, c)]
                seen.add((r, c))
                cells = []
                while todo:
                    y, x = todo.pop()
                    cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            q = (y + dy, x + dx)
                            if 0 <= q[0] < h and 0 <= q[1] < w and grid[q[0]][q[1]] and q not in seen:
                                seen.add(q)
                                todo.append(q)
                comps.append(cells)
    cells = max(comps, key=lambda p: max(r for r, c in p))
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    return [[1 if grid[r][c] else 0 for c in range(c0, c1 + 1)] for r in range(r0, r1 + 1)]
